/**
 * Exact money helpers for the propose tools. No floats touch an amount the
 * model typed: the decimal string is parsed digit by digit into integer minor
 * units, shares are built with the SAME largest-remainder rule the app uses
 * (PORT of src/lib/money/distribute.ts, parity-tested in money.test.ts against
 * fixtures generated by running the client function), and amounts are printed
 * from integers.
 */
import { getCurrencyExponent } from '../../../_shared/money/currencyExponent.ts'

/** The currencies the app's picker offers (src/features/expenses/lib/currencyList.ts). */
export const KNOWN_CURRENCIES: ReadonlySet<string> = new Set(
  'GBP EUR USD JPY CHF AUD CAD NZD CNY HKD SGD KRW INR THB VND IDR MYR PHP TWD AED SAR ILS TRY ZAR EGP MXN BRL ARS CLP COP PEN SEK NOK DKK PLN CZK HUF RON ISK RUB BHD KWD OMR JOD QAR PKR BDT LKR NPR FJD'.split(' '),
)

/** Largest single expense the assistant will propose (minor units): 99,999,999.99 in a 2-decimal currency. */
export const MAX_MINOR = 9_999_999_999

export function isKnownCurrency(code: string, tripBase?: string): boolean {
  return KNOWN_CURRENCIES.has(code) || (!!tripBase && code === tripBase)
}

/**
 * "40", "40.5", "40.50" -> minor units, exactly. Rejects signs, commas, exponents, spaces and more
 * decimals than the currency has (never rounds silently). Returns null when it cannot be read.
 */
export function parseDecimalToMinor(text: string, currency: string): number | null {
  const m = /^(\d{1,9})(?:\.(\d{1,6}))?$/.exec(text.trim())
  if (!m) return null
  const exp = getCurrencyExponent(currency)
  let frac = m[2] ?? ''
  // Trailing zeros beyond the currency's decimals are harmless ("40.000" GBP); other digits are not.
  while (frac.length > exp && frac.endsWith('0')) frac = frac.slice(0, -1)
  if (frac.length > exp) return null
  const minor = Number(m[1] + frac.padEnd(exp, '0'))
  if (!Number.isSafeInteger(minor) || minor > MAX_MINOR) return null
  return minor
}

/** PORT of src/lib/money/distribute.ts largestRemainderDistribute (keep identical). */
export function largestRemainderDistribute(totalMinor: number, weights: number[]): number[] {
  if (!Number.isInteger(totalMinor)) {
    throw new Error(`largestRemainderDistribute: totalMinor must be an integer, got ${totalMinor}`)
  }
  if (weights.length === 0) {
    if (totalMinor !== 0) {
      throw new Error('largestRemainderDistribute: cannot distribute a non-zero total across zero weights')
    }
    return []
  }
  if (weights.some((w) => w < 0 || !Number.isFinite(w))) {
    throw new Error('largestRemainderDistribute: weights must be non-negative finite numbers')
  }

  const weightSum = weights.reduce((a, b) => a + b, 0)
  if (weightSum === 0) {
    return largestRemainderDistribute(totalMinor, weights.map(() => 1))
  }

  const sign = totalMinor < 0 ? -1 : 1
  const magnitude = Math.abs(totalMinor)

  const exactShares = weights.map((w) => (w / weightSum) * magnitude)
  const floorShares = exactShares.map((s) => Math.floor(s))
  const remainders = exactShares.map((s, i) => s - floorShares[i])

  let allocated = floorShares.reduce((a, b) => a + b, 0)
  let remaining = magnitude - allocated

  const order = weights
    .map((_, i) => i)
    .sort((a, b) => remainders[b] - remainders[a] || a - b)

  const shares = [...floorShares]
  for (let k = 0; k < order.length && remaining > 0; k++) {
    shares[order[k]] += 1
    remaining -= 1
  }

  allocated = shares.reduce((a, b) => a + b, 0)
  if (allocated !== magnitude) {
    const diff = magnitude - allocated
    const biggestIndex = order[0] ?? 0
    shares[biggestIndex] += diff
  }

  return shares.map((s) => s * sign)
}

/** Equal split of a total over n people, exactly as the app's "equal" mode does it. */
export function equalShares(totalMinor: number, n: number): number[] {
  return largestRemainderDistribute(totalMinor, Array.from({ length: n }, () => 1))
}

const SYMBOLS: Record<string, string> = {
  GBP: '£', EUR: '€', USD: '$', CHF: 'CHF ', JPY: '¥', AUD: 'A$', CAD: 'C$', KRW: '₩', CNY: 'CN¥',
  HKD: 'HK$', SGD: 'S$', NZD: 'NZ$', INR: '₹', THB: '฿',
}

function group3(digits: string): string {
  return digits.replace(/\B(?=(\d{3})+(?!\d))/g, ',')
}

/** Integer minor units -> "£40.00" (the app's 'exact' mode: full minor units, en-GB grouping). Integer maths only. */
export function formatMinor(minor: number, currency: string): string {
  const exp = getCurrencyExponent(currency)
  const abs = Math.abs(minor)
  const scale = 10 ** exp
  const whole = Math.floor(abs / scale)
  const frac = exp > 0 ? String(abs % scale).padStart(exp, '0') : ''
  const symbol = SYMBOLS[currency] ?? `${currency} `
  return `${minor < 0 && abs !== 0 ? '-' : ''}${symbol}${group3(String(whole))}${exp > 0 ? `.${frac}` : ''}`
}

/** Decimal string with the currency's own number of decimals ("40.00", "5000") from minor units. */
export function minorToDecimal(minor: number, currency: string): string {
  const exp = getCurrencyExponent(currency)
  const scale = 10 ** exp
  const abs = Math.abs(minor)
  const whole = Math.floor(abs / scale)
  const frac = exp > 0 ? `.${String(abs % scale).padStart(exp, '0')}` : ''
  return `${minor < 0 ? '-' : ''}${whole}${frac}`
}
